<template>
  <div class="d-flex flex-column align-end">
    <p
      class="text-h5 productProductNameTicket--text text--lighten-1 font-weight-bold"
    >
      {{ formatNumberFromDbToCurrency(totalProductPrice) }}
    </p>
    <v-tooltip v-if="canShowAlertCustomPromotions" left>
      <template v-slot:activator="{ on }">
        <v-btn
          color="warning"
          depressed
          icon
          class="button-effect"
          small
          v-on="on"
          @click.prevent.stop="showCustomPromotions"
        >
          <v-icon>
            mdi-sale
          </v-icon>
        </v-btn>
      </template>
      <span>{{
        getTranslatedText('salesView.ticket.promotions.seePromotions')
      }}</span>
    </v-tooltip>
  </div>
</template>

<script>
import { mapActions, mapGetters } from 'vuex'

import { promotions } from '@/config/promotions'

import paymentMethods from '@/config/paymentMethods'

import { getTotalProductPrice } from '@/tools/ticket'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { getTranslatedText } from '@/tools/data'

import salesViewActions from '@/store/salesView/actions.types'

export default {
  name: 'ProductTotal',
  props: {
    product: {
      type: Object,
      required: true,
    },
    payOption: {
      type: [String, Number],
      required: true,
    },
    promotionTicketId: {
      type: Number,
      required: true,
    },
    priceKey: {
      type: String,
      required: true,
    },
  },
  computed: {
    ...mapGetters('customPromotions', [
      'getCustomPromotionsByProductAndTypeWithFilters',
    ]),
    canShowAlertCustomPromotions() {
      if (
        this.$route.name !== 'Sales' ||
        this.promotionTicketId === promotions.SALE_TICKET_AT_COST ||
        paymentMethods.isOwnerSale(this.payOption)
      ) {
        return false
      }
      const filterBy = { isActive: true, product: this.product, sale: true }
      const moreForLessByProduct = this.getCustomPromotionsByProductAndTypeWithFilters(
        promotions.SALE_ITEM_MORE_FOR_LESS,
        filterBy
      )[this.product.id]
      const comboByProduct = this.getCustomPromotionsByProductAndTypeWithFilters(
        promotions.SALE_ITEM_COMBO,
        filterBy
      )[this.product.id]
      return !!moreForLessByProduct || !!comboByProduct
    },
    totalProductPrice() {
      return getTotalProductPrice(this.product, this.priceKey)
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('salesView', [
      salesViewActions.setListProductPromotionsDialogStatus,
    ]),
    formatNumberFromDbToCurrency,
    showCustomPromotions() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Sales',
        screen: 'TicketProduct',
        name: 'Show custom promotions dialog',
      })
      this[salesViewActions.setListProductPromotionsDialogStatus]({
        isOpen: true,
        product: this.product,
      })
    },
  },
}
</script>

<style scoped lang="scss">
p {
  margin-bottom: 0;
}
.button-effect {
  animation: grow 8s ease-in-out infinite;
}
@keyframes grow {
  0%,
  3%,
  9%,
  15%,
  100% {
    transform: scale(1);
  }
  6%,
  12% {
    transform: scale(1.25);
  }
}
</style>
