<template>
  <div class="d-flex flex-column">
    <p
      class="text-h6 productProductNameTicket--text text--lighten-1 text-ellipsis"
    >
      {{ productName }}
    </p>
    <div class="d-flex product-info__extra align-center">
      <div v-if="!airTimeProduct" class="d-flex align-center product-price">
        <v-icon :color="iconColor" class="pr-1">
          $currencyUsdCircle
        </v-icon>
        <v-icon
          v-if="differenceBetweenUnitPriceAndDbPrice && isSaleSection"
          class="pr-1"
          color="warning"
        >
          {{
            unitPriceIsLessThanDbPrice
              ? 'mdi-chevron-down-circle-outline'
              : 'mdi-chevron-up-circle-outline'
          }}
        </v-icon>
        <p class="text-h6" :class="priceColor" v-if="product[priceKey] >= 0">
          {{ formatNumberFromDbToCurrency(product[priceKey]) }}
        </p>
        <p class="text-h6 error--text text--lighten-1" v-else>
          ?
        </p>
        <p
          v-if="hasPromotions || hasProductTicketAtCostApplied"
          class="pl-2 text-h6 text-decoration-line-through"
          :class="oldPriceColor"
        >
          {{ formatNumberFromDbToCurrency(product[priceWithoutPromotionKey]) }}
        </p>
      </div>
      <div
        v-if="!airTimeProduct && !genericProduct && !isOperationSection"
        class="d-flex align-center product-stock"
      >
        <v-icon color="primary" class="pr-1">
          mdi-basket-fill
        </v-icon>
        <p class="text-h6 primary--text text--lighten-1">
          {{ product.stock }}
          {{
            getTranslatedText(
              `salesView.ticket.${
                byWeightProduct ? 'grams' : 'pieces'
              }Abbreviation`
            )
          }}
        </p>
      </div>
    </div>
    <div v-if="airTimeProduct && !isOperationSection">
      <v-icon color="primary" class="pr-1">
        mdi-phone-classic
      </v-icon>
      <p class="text-h6 primary--text text--lighten-1">
        {{ product.phoneNumber }}
      </p>
    </div>
    <div v-if="airTimeProduct && !isOperationSection">
      <v-icon color="primary" class="pr-1">
        mdi-file-code-outline
      </v-icon>
      <p class="text-h6 primary--text text--lighten-1">
        {{ product.reference }}
      </p>
    </div>
  </div>
</template>

<script>
import { promotions } from '@/config/promotions'

import { getTranslatedText } from '@/tools/data'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { hasProductPromotion } from '@/tools/promotions'

export default {
  name: 'ProductInfo',
  props: {
    product: {
      type: Object,
      required: true,
    },
    payOption: {
      type: [String, Number],
      required: true,
    },
    promotionTicketId: {
      type: Number,
      required: true,
    },
    priceKey: {
      type: String,
      required: true,
    },
    priceWithoutPromotionKey: {
      type: String,
      required: true,
    },
  },
  computed: {
    isOperationSection() {
      return (
        this.$route.name === 'Operations' || this.$route.name === 'Customers'
      )
    },
    isSaleSection() {
      return this.$route.name === 'Sales'
    },
    iconColor() {
      return this.isOperationSection
        ? 'productProductNameTicket lighten-2'
        : 'primary lighten-1'
    },
    priceColor() {
      return this.isOperationSection
        ? 'productProductNameTicket--text text--lighten-2'
        : 'primary--text text--lighten-1'
    },
    oldPriceColor() {
      return this.isOperationSection
        ? 'productProductNameTicket--text text--lighten-3'
        : 'productProductNameTicket--text text--lighten-1'
    },
    productName() {
      if (
        parseInt(this.product.upc) > 0 ||
        /^[A-Za-z0-9]+$/.test(this.product.upc)
      ) {
        return `${this.product.name} ${this.product.description || ''}`
      }
      return this.getTranslatedText('salesView.ticket.genericProduct')
    },
    airTimeProduct() {
      return this.product.isAirtime === 1
    },
    genericProduct() {
      return this.product.isGeneric === 1
    },
    byWeightProduct() {
      return this.product.isGramaje === 1
    },
    differenceBetweenUnitPriceAndDbPrice() {
      if (!this.product.unitPrice || !this.product.dbPrice) return false
      return (
        this.unitPriceIsLessThanDbPrice ||
        this.product.unitPrice > this.product.dbPrice
      )
    },
    unitPriceIsLessThanDbPrice() {
      return this.product.unitPrice < this.product.dbPrice
    },
    hasPromotions() {
      if (this.product.promotions && this.product.promotions.length > 0) {
        return true
      }
      if (
        !this.product.promotionTypeId ||
        this.product.promotionTypeId === promotions.SALE_ITEM_COMBO
      ) {
        return false
      }
      return hasProductPromotion(this.product.promotionTypeId)
    },
    hasProductTicketAtCostApplied() {
      return (
        (this.promotionTicketId === promotions.SALE_TICKET_AT_COST ||
          this.product.promotionTypeId === promotions.SALE_TICKET_AT_COST) &&
        this.product.cost > 0 &&
        this.product.isGeneric !== 1
      )
    },
  },
  methods: {
    formatNumberFromDbToCurrency,
    getTranslatedText,
  },
}
</script>

<style scoped lang="scss">
p {
  margin-bottom: 0;
}
.text-ellipsis {
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  max-width: 95%;
  box-sizing: border-box;
  flex-shrink: 1;
}
.product-info__extra {
  gap: 20px;
}
</style>
