<template>
  <p class="large-font">
    <strong v-if="data.storeName">{{ data.storeName }}</strong>
    <br v-if="data.storeName" />
    <span v-if="data.storeAddress">{{ data.storeAddress }}</span>
    <br v-if="data.storeAddress" />
    <span v-if="data.storePostalCode">{{ data.storePostalCode }} </span>
    <span v-if="data.storeTown">{{ data.storeTown }} </span>
    <span v-if="state">({{ state.name }})</span>
    <br v-if="data.state" />
    <span v-if="data.storeLandlinePhone">
      {{ getTranslatedText('ticketToPrint.header.phone') }}
      {{ data.storeLandlinePhone }}
      <br />
    </span>
    <br />
    {{ getTranslatedText('ticketToPrint.header.attendedBy') }}
    {{ name }}<br />
    {{ getTranslatedText('ticketToPrint.header.date') }}
    {{ operationDate }}
    <br />
    {{ getTranslatedText('ticketToPrint.code') }}
    {{ ticketCode }}
  </p>
</template>

<script>
import { mapState } from 'vuex'

import states from '@/config/states'

import { getTranslatedText } from '@/tools/data'
import { getDateWithFormat } from '@/tools/dates'

export default {
  name: 'HeaderSaleTicket',
  props: {
    operationDate: {
      type: String,
      required: true,
    },
    name: {
      type: String,
      required: true,
    },
    ticketCode: {
      type: String,
      required: true,
    },
  },
  computed: {
    ...mapState('account', ['data']),
    state() {
      return states[this.data.country.localeIsoCode].find(
        state => state.id === this.data.storeState
      )
    },
  },
  methods: {
    getDateWithFormat,
    getTranslatedText,
  },
}
</script>
