<template>
  <div>
    <div v-for="combo in combos" :key="combo.id" class="product-container">
      <span>> Combo:</span>
      <span>
        {{ combo.promotions.firstProduct.name }}
        {{ combo.promotions.firstProduct.alternativeName }}
      </span>
      <span>
        {{ combo.promotions.secondProduct.name }}
        {{ combo.promotions.secondProduct.alternativeName }}
      </span>
      <div class="product-detail cols-3">
        <span>
          {{ combo.quantity }}
        </span>
        <span class="centered">
          {{ formatNumberFromDbToCurrency(combo.promotions.total) }}
        </span>
        <span class="text-right">
          {{
            formatNumberFromDbToCurrency(
              combo.promotions.total * combo.quantity
            )
          }}
        </span>
      </div>
    </div>
  </div>
</template>

<script>
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

export default {
  name: 'CombosListTicket',
  props: {
    combos: {
      type: Array,
      default: () => [],
    },
  },
  methods: { formatNumberFromDbToCurrency },
}
</script>
