<template>
  <div class="btn-actions">
    <v-btn
      v-if="isHover && actions.add && actions.add.show"
      class="btn-actions__add"
      absolute
      icon
      v-on="actions.add.on"
    >
      <v-icon color="primary">mdi-plus-circle</v-icon>
    </v-btn>
    <v-btn
      v-if="isHover && actions.subtract && actions.subtract.show"
      class="btn-actions__subtract"
      absolute
      icon
      v-on="actions.subtract.on"
    >
      <v-icon color="primary">mdi-minus-circle</v-icon>
    </v-btn>
    <v-btn
      v-if="isHover && actions.delete && actions.delete.show"
      class="btn-actions__delete"
      absolute
      fab
      x-small
      v-on="actions.delete.on"
    >
      <v-icon :color="deleteIconColor">mdi-delete</v-icon>
    </v-btn>
    <v-btn
      v-if="isHover && actions.edit && actions.edit.show"
      class="btn-actions__edit"
      absolute
      fab
      x-small
      v-on="actions.edit.on"
    >
      <v-icon color="primary">mdi-square-edit-outline</v-icon>
    </v-btn>
  </div>
</template>

<script>
export default {
  name: 'ActionsButtons',
  props: {
    isHover: {
      type: Boolean,
      default: false,
    },
    actions: {
      type: Object,
      required: true,
    },
  },
  computed: {
    deleteIconColor() {
      if (this.$route.name === 'Operations' || this.$route.name === 'Customers')
        return 'warning'
      return 'primary'
    },
  },
}
</script>

<style scoped lang="scss">
.btn-actions {
  button {
    z-index: 100;
  }
  &__add {
    top: 20px;
    left: 6px;
  }
  &__subtract {
    bottom: 6px;
    left: 6px;
  }
  &__delete {
    top: 4px;
    right: -4px;
  }
  &__edit {
    bottom: -6px;
    right: -4px;
  }
}
</style>
