<template>
  <div class="ticket-to-print">
    <img :src="ticketLogo" class="brand-logo" :alt="`${data.name} logo`" />
    <HeaderSaleTicket
      v-if="isSaleTicket"
      :name="name"
      :operation-date="ticketDate"
      :ticket-code="ticketCode"
    />
    <HeaderOwnerSaleTicket
      v-if="isOwnerSaleTicket"
      :name="name"
      :operation-date="ticketDate"
      :ticket-code="ticketCode"
    />
    <HeaderPurchaseTicket
      v-if="isPurchaseTicket"
      :name="name"
      :operation-date="ticketDate"
      :details="details"
      :ticket-code="ticketCode"
    />
    <ItemsListTicket
      :products="products"
      :returnProducts="returnProducts"
      :operation-type="operationType"
      :isSaleTicket="isSaleTicket"
      :isPurchaseTicket="isPurchaseTicket"
      :combos="combos"
      :isCopy="isCopy"
    />
    <br />
    <TotalTicket
      :ticket-promotion="ticketPromotion"
      :total-price="totalPrice"
      :amountToDiscount="amountToDiscount"
      :products="products"
      :isPurchaseTicket="isPurchaseTicket"
    />
    <div v-if="isCreditSaleTicket">
      <FooterCreditSaleTicket
        :details="details"
        :total-price="totalPrice"
        :is-copy="isCopy"
      />
    </div>
    <div v-else-if="isSaleTicket && !isCreditSaleTicket">
      <FooterSaleTicket
        :total-price="totalPrice"
        :amountToDiscount="amountToDiscount"
        :details="details"
      />
    </div>
    <p class="small-font" v-if="isSaleTicket">
      ----------------------------------------------------------
    </p>
    <p class="centered large-font" v-if="isSaleTicket">
      {{ getTranslatedText('ticketToPrint.thanks') }}
    </p>
    <div class="small-font centered">
      <b>*** {{ ticketType }} ***</b>
    </div>
  </div>
</template>

<script>
import { mapState } from 'vuex'

import tiendatekLogo from '@/config/tiendatekLogoBase64'
import { idOperations } from '@/config/cashOperationsVariables'
import { returnTypes } from '@/config/returnProductTypes'

import { getTranslatedText } from '@/tools/data'
import {
  getTotalTicketPrice,
  getTotalTicketPriceOwnerSale,
  getTicketCodeFromDate,
} from '@/tools/ticket'
import {
  formatNumberFromDbToCurrency,
  formatNumberToCurrency,
  formatNumberToDb,
  roundToNearestMultiple,
} from '@/tools/numbersFormat'
import { discountTypes, getAmountFromPercent } from '@/tools/promotions'
import salesTools from '@/tools/sales'
import { getDateWithFormat } from '@/tools/dates'

import ItemsListTicket from '@/components/TicketToPrint/ItemsListTicket'
import HeaderSaleTicket from '@/components/TicketToPrint/HeaderSaleTicket'
import HeaderOwnerSaleTicket from '@/components/TicketToPrint/HeaderOwnerSaleTicket'
import HeaderPurchaseTicket from '@/components/TicketToPrint/HeaderPurchaseTicket'
import TotalTicket from '@/components/TicketToPrint/TotalTicket'
import FooterCreditSaleTicket from '@/components/TicketToPrint/FooterCreditSaleTicket'
import FooterSaleTicket from '@/components/TicketToPrint/FooterSaleTicket'

export default {
  name: 'TicketToPrint',
  components: {
    FooterSaleTicket,
    FooterCreditSaleTicket,
    TotalTicket,
    ItemsListTicket,
    HeaderPurchaseTicket,
    HeaderOwnerSaleTicket,
    HeaderSaleTicket,
  },
  props: {
    products: {
      type: Array,
      required: true,
    },
    returnProducts: {
      type: Array,
      default: () => [],
    },
    isCopy: {
      type: Boolean,
      default: false,
    },
    operationType: {
      type: Number,
      required: true,
    },
    details: {
      type: Object,
    },
    operationDate: {
      type: String,
      required: true,
    },
    ticketPromotion: {
      type: Object,
      default: null,
    },
    combos: {
      type: Array,
      default: () => [],
    },
  },
  computed: {
    ...mapState('account', ['data']),
    ...mapState('usersView', ['selectedUser']),
    ...mapState('app', ['showCustomerDataTicket']),
    isCreditSaleTicket() {
      return this.operationType === idOperations.ID_OPERATION_CREDIT_SALE
    },
    isSaleTicket() {
      return [
        idOperations.ID_OPERATION_CASH_SALE,
        idOperations.ID_OPERATION_CREDIT_SALE,
        idOperations.ID_OPERATION_EXTERNAL_PAYMENT_SALE,
      ].includes(this.operationType)
    },
    isOwnerSaleTicket() {
      return salesTools.isOwnerSale(this.operationType)
    },
    isPurchaseTicket() {
      return [
        idOperations.ID_OPERATION_CREDIT_PURCHASE,
        idOperations.ID_OPERATION_CASH_PURCHASE,
      ].includes(this.operationType)
    },
    ticketType() {
      return this.isCopy
        ? this.getTranslatedText('ticketToPrint.copy')
        : this.getTranslatedText('ticketToPrint.original')
    },
    ticketLogo() {
      return `data:image/jpg;base64,${
        this.data.storeImage.length === 0 ? tiendatekLogo : this.data.storeImage
      }`
    },
    name() {
      let name =
        this.selectedUser.name === 'admin' && this.data.name.length > 2
          ? this.data.name
          : this.selectedUser.name
      return name ? name.split(' ')[0] : ''
    },
    amountToDiscount() {
      if (!this.ticketPromotion) return 0
      if (
        discountTypes.isDiscountPerAmount(this.ticketPromotion.promotionType)
      ) {
        return this.ticketPromotion.promotion
      }
      return getAmountFromPercent(
        this.ticketPromotion.promotion,
        this.totalPrice
      )
    },
    totalPrice() {
      if (this.isOwnerSaleTicket) {
        return getTotalTicketPriceOwnerSale(this.products)
      }
      const totalProducts = getTotalTicketPrice(this.products)
      return roundToNearestMultiple(
        parseInt(totalProducts) +
          parseInt(-this.returnProductsTotal) +
          parseInt(this.combosTotal)
      )
    },
    returnProductsTotal() {
      return this.returnProducts
        .reduce((total, returnItem) => {
          const { returnType, amountToDiscount } = returnItem
          const subtotal =
            returnType === returnTypes.DISCOUNT ? amountToDiscount : 0
          return total + subtotal
        }, 0)
        .toFixed(0)
    },
    combosTotal() {
      return this.combos.reduce((total, combo) => {
        return total + combo.promotions.total * combo.quantity
      }, 0)
    },
    ticketDate() {
      return this.operationDate && this.operationDate !== ''
        ? getDateWithFormat(this.operationDate, 'DD-MM-YYYY, HH:mm:ss')
        : ''
    },
    ticketCode() {
      return this.operationDate && this.operationDate !== ''
        ? getTicketCodeFromDate(this.operationDate)
        : ''
    },
  },
  methods: {
    formatNumberToDb,
    formatNumberToCurrency,
    getTranslatedText,
    formatNumberFromDbToCurrency,
  },
}
</script>
