<template>
  <div>
    <p class="small-font">
      ----------------------------------------------------------
    </p>
    <p class="large-font centered">
      {{ getTranslatedText('ticketToPrint.footer.customerStatus') }}
    </p>
    <p class="medium-font">
      {{ getTranslatedText('ticketToPrint.footer.customer') }}
      {{ details.customer.name }}<br />
      {{ getTranslatedText('ticketToPrint.footer.creditLimit') }}
      {{ formatNumberFromDbToCurrency(details.customer.debtLimit) }}<br />
      {{ getTranslatedText('ticketToPrint.footer.unpaidSales') }}
      {{ details.customer.unpaidSalesNumber + (isCopy ? 0 : 1) }}<br />
      {{ getTranslatedText('ticketToPrint.footer.debt') }}
      {{
        formatNumberFromDbToCurrency(
          details.customer.debt + (isCopy ? 0 : totalPrice)
        )
      }}<br />
    </p>
  </div>
</template>

<script>
import { getTranslatedText } from '@/tools/data'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

export default {
  name: 'FooterCreditSaleTicket',
  props: {
    details: {
      type: Object,
      required: true,
    },
    isCopy: {
      type: Boolean,
      default: false,
    },
    totalPrice: {
      type: Number,
      default: 0,
    },
  },
  methods: {
    getTranslatedText,
    formatNumberFromDbToCurrency,
  },
}
</script>
