<template>
  <div class="d-flex flex-column align-center">
    <p
      class="text-h5 productProductNameTicket--text text--lighten-1 font-weight-bold mb-0"
      v-if="product.quantity !== 0"
    >
      {{ product.quantity }}
    </p>
    <p class="text-h5 error--text text--lighten-1 font-weight-bold mb-0" v-else>
      ?
    </p>
    <p
      class="text-subtitle-1 text--lighten-1 mb-0"
      :class="{
        'error--text': product.quantity === 0,
        'unitTypeTicket--text': product.quantity !== 0,
      }"
    >
      {{ getTranslatedText(unitType) }}
    </p>
  </div>
</template>

<script>
import { getTranslatedText } from '@/tools/data'

export default {
  name: 'ProductQuantity',
  props: {
    product: {
      type: Object,
      required: true,
    },
    text: {
      type: String,
      default: null,
    },
  },
  computed: {
    unitType() {
      if (this.text) return this.text
      if (this.product.isGramaje === 1) return 'salesView.ticket.grams'
      if (this.product.isAirtime === 1) return 'salesView.ticket.recharge'
      if (
        this.product.isOpenProduct === 1 &&
        this.product.openProductType === 0
      ) {
        return 'salesView.ticket.packages'
      }
      return 'salesView.ticket.pieces'
    },
  },
  methods: {
    getTranslatedText,
  },
}
</script>
