<template>
  <div>
    <div v-if="isPurchaseTicket">
      <span class="small-font">
        ----------------------------------------------------------
      </span>
      <div class="total-row">
        <span class="medium-font">
          {{ getTranslatedText('ticketToPrint.taxes.tax') }}
        </span>
        <span class="medium-font">
          {{ formatNumberFromDbToCurrency(taxesBreakdown.totalTax) }}
        </span>
      </div>
      <div class="total-row">
        <span class="medium-font">
          {{ getTranslatedText('ticketToPrint.taxes.netPrice') }}
        </span>
        <span class="medium-font">
          {{ formatNumberFromDbToCurrency(taxesBreakdown.netPrice) }}
        </span>
      </div>
      <span class="small-font">
        ----------------------------------------------------------
      </span>
    </div>
    <div v-if="hasTicketAtCostPromotion" class="total-row">
      <strong class="medium-font">
        {{
          getTranslatedText('ticketToPrint.totalTicket.promotion.ticketAtCost')
        }}
      </strong>
    </div>
    <div v-if="ticketPromotion && !hasTicketAtCostPromotion">
      <div class="total-row">
        <strong class="medium-font">
          {{
            getTranslatedText('ticketToPrint.totalTicket.promotion.discount')
          }}:
        </strong>
        <strong class="medium-font">{{ promotion }}</strong>
      </div>
      <div class="total-row">
        <span />
        <span style="text-decoration: line-through;">
          {{ formatNumberFromDbToCurrency(totalPrice) }}
        </span>
      </div>
      <div class="total-row">
        <strong>{{
          getTranslatedText('ticketToPrint.totalTicket.total')
        }}</strong>
        <strong>
          {{ formatNumberFromDbToCurrency(totalPrice - amountToDiscount) }}
        </strong>
      </div>
    </div>
    <div v-else class="total-row">
      <strong>{{
        getTranslatedText('ticketToPrint.totalTicket.total')
      }}</strong>
      <strong>
        {{ formatNumberFromDbToCurrency(totalPrice) }}
      </strong>
    </div>
  </div>
</template>

<script>
import { promotions } from '@/config/promotions'

import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { getTranslatedText } from '@/tools/data'
import { discountTypes } from '@/tools/promotions'
import {
  getTotalProductPrice,
  getTotalProductPriceWithPromotion,
} from '@/tools/ticket'
import { applyTax } from '@/tools/purchases/tools'

export default {
  name: 'TotalTicket',
  props: {
    ticketPromotion: {
      type: Object,
      default: null,
    },
    totalPrice: {
      type: Number,
      default: 0,
    },
    products: {
      type: Array,
      default: () => [],
    },
    amountToDiscount: {
      type: Number,
      default: 0,
    },
    isPurchaseTicket: {
      type: Boolean,
      default: false,
    },
  },
  computed: {
    promotion() {
      if (
        discountTypes.isDiscountPerAmount(this.ticketPromotion.promotionType)
      ) {
        return formatNumberFromDbToCurrency(this.ticketPromotion.promotion)
      }
      return `${
        this.ticketPromotion.promotion
      }% (${formatNumberFromDbToCurrency(this.amountToDiscount)})`
    },
    hasTicketAtCostPromotion() {
      return (
        (this.ticketPromotion &&
          this.ticketPromotion.promotionTicketId ===
            promotions.SALE_TICKET_AT_COST) ||
        this.products.some(
          product => product.promotionTypeId === promotions.SALE_TICKET_AT_COST
        )
      )
    },
    taxesBreakdown() {
      const data = { netPrice: 0, totalTax: 0 }
      this.products.forEach(product => {
        const totalPrice = this.getTotalProductPrice(product)
        const netPrice = Math.round(totalPrice / applyTax(product.iva))
        data.netPrice += netPrice
        data.totalTax += totalPrice - netPrice
      })
      return data
    },
  },
  methods: {
    getTranslatedText,
    formatNumberFromDbToCurrency,
    getTotalProductPrice(product) {
      return Math.round(
        getTotalProductPriceWithPromotion({
          ...product,
          cost: product.price,
          promotionType: product.promotionTypeId,
          discountPercent: product.discount,
          discountAmount: this.getDiscountAmount(product),
        })
      )
    },
    getDiscountAmount(product) {
      const originalTotalWithIVA =
        getTotalProductPrice(product, 'costWithoutTaxAndPromotion') *
        applyTax(product.iva)
      const discountedTotalWithIVA = getTotalProductPrice(product, 'price')
      return originalTotalWithIVA - discountedTotalWithIVA
    },
  },
}
</script>
