<template>
  <p class="large-font">
    <span v-if="data.storeName">{{ data.storeName }}</span>
    <br v-if="data.storeName" />
    {{ getTranslatedText('ticketToPrint.header.vendor') }}
    <strong>{{ details.vendor.name }}</strong>
    <br />
    <span v-if="details.vendor.tributaryId">
      {{ getTranslatedText('ticketToPrint.header.tributaryId') }}
      <span>{{ details.vendor.tributaryId }} </span>
    </span>
    <br />
    <span v-if="details.vendor.sellerName">
      {{ getTranslatedText('ticketToPrint.header.sellerName') }}
      <span>{{ details.vendor.sellerName }}</span>
      <br />
    </span>
    <span v-if="details.vendor.sellerPhone">
      {{ getTranslatedText('ticketToPrint.header.phone') }}
      <span>{{ details.vendor.sellerPhone }}</span>
      <br />
    </span>
    {{ getTranslatedText('ticketToPrint.header.purchaseBy') }}
    {{ name }}<br />
    {{ getTranslatedText('ticketToPrint.header.date') }}
    {{ operationDate }}
    <br />
    {{ getTranslatedText('ticketToPrint.code') }}
    {{ ticketCode }}
  </p>
</template>
<script>
import { mapState } from 'vuex'

import { getTranslatedText } from '@/tools/data'

export default {
  name: 'HeaderPurchaseTicket',
  props: {
    details: {
      type: Object,
      required: true,
    },
    operationDate: {
      type: String,
      required: true,
    },
    name: {
      type: String,
      required: true,
    },
    ticketCode: {
      type: String,
      required: true,
    },
  },
  computed: {
    ...mapState('account', ['data']),
  },
  methods: {
    getTranslatedText,
  },
}
</script>
