<template>
  <div v-if="showCashChange">
    <div class="total-row">
      <span>
        {{ getTranslatedText('ticketToPrint.footer.cash') }}
      </span>
      <span class="text-right">
        {{
          !!details.cash_amount
            ? formatNumberFromDbToCurrency(details.cash_amount)
            : formatNumberFromDbToCurrency(totalPrice - amountToDiscount)
        }}
      </span>
    </div>
    <div class="total-row">
      <span>
        {{ getTranslatedText('ticketToPrint.footer.change') }}
      </span>
      <span class="text-right">
        {{
          !!details.cash_amount
            ? formatNumberFromDbToCurrency(
                details.cash_amount - (totalPrice - amountToDiscount)
              )
            : formatNumberToCurrency(0)
        }}
      </span>
    </div>
  </div>
  <div v-else class="external-payment-method">
    <span>
      {{ externalPaymentMethod }}
    </span>
    <span class="small-font" v-if="commissions !== ''">
      {{ commissions }}
    </span>
  </div>
</template>

<script>
import { mapState } from 'vuex'

import paymentMethods from '@/config/paymentMethods'

import { getTranslatedText } from '@/tools/data'
import {
  formatNumberFromDbToCurrency,
  formatNumberToCurrency,
  formatNumberToDb,
} from '@/tools/numbersFormat'

export default {
  name: 'FooterSaleTicket',
  props: {
    totalPrice: {
      type: Number,
      default: 0,
    },
    amountToDiscount: {
      type: Number,
      default: 0,
    },
    details: {
      type: Object,
      required: true,
    },
  },
  computed: {
    ...mapState('salesView', ['paymentProvidersByType']),
    showCashChange() {
      return paymentMethods.isCashSale(
        paymentMethods.getPaymentMethodKeyFromId(this.details.payment_method)
      )
    },
    paymentMethodKey() {
      return paymentMethods.getPaymentMethodKeyFromId(
        this.details.payment_method
      )
    },
    paymentProvider() {
      if (!paymentMethods.isExternalPaymentSale(this.paymentMethodKey)) {
        return {}
      }
      return this.paymentProvidersByType[this.paymentMethodKey].find(
        provider => provider.id === this.details.payment_method_provider
      )
    },
    externalPaymentMethod() {
      let paymentMethodText = ''
      if (
        paymentMethods.defaultPaymentMethods.includes(this.paymentMethodKey)
      ) {
        paymentMethodText = this.getTranslatedText(
          `ticketToPrint.footer.${this.paymentMethodKey}`
        )
      }
      return `${paymentMethodText}${this.paymentProvider.label}`
    },
    commissions() {
      if (
        !paymentMethods.isCardSale(this.paymentProvider.type) ||
        this.paymentProvider.commissions <= 0
      ) {
        return ''
      }
      return this.getTranslatedText(
        'ticketToPrint.footer.commissions',
        this.paymentProvider.commissions
      )
    },
  },
  methods: {
    getTranslatedText,
    formatNumberFromDbToCurrency,
    formatNumberToDb,
    formatNumberToCurrency,
  },
}
</script>
