import { promotions } from '@/config/promotions'

import {
  convertByWeightQuantity,
  formatNumberToDb,
} from '@/tools/numbersFormat'
import { discountTypes } from '@/tools/promotions'

export const applyTax = tax => tax / 100 + 1

export const getTotal = (isGramaje, quantity, cost, iva, applyTax = true) => {
  const tax = iva / 100 + 1
  const baseAmount =
    isGramaje === 1
      ? convertByWeightQuantity(quantity, false) * cost
      : quantity * cost
  const totalAmount = applyTax ? baseAmount * tax : baseAmount
  return Number(totalAmount.toFixed(2))
}

export const getTotalExistences = (factor, existences, existencesPack) => {
  if (factor <= 1) {
    return existences
  }
  return Math.floor(existencesPack) * factor + Math.floor(existences)
}

export const calculateUnitaryCost = (formPayload, isGramaje) => {
  const {
    promotionTypeId,
    cost,
    quantity,
    freeUnits,
    tax,
    type,
    discount,
  } = formPayload
  switch (promotionTypeId) {
    case promotions.NONE:
      return formatNumberToDb(cost * applyTax(tax))
    case promotions.PURCHASE_ITEM_FREE_PRODUCT:
      return formatNumberToDb(0)
    case promotions.PURCHASE_ITEM_FREE_UNITS: {
      const unitaryCost = (quantity * cost) / (quantity + freeUnits)
      return formatNumberToDb(unitaryCost * applyTax(tax))
    }
    case promotions.PURCHASE_ITEM_SUBTOTAL_DISCOUNT: {
      const totalWithIVA = getTotal(isGramaje, quantity, cost, tax)
      const discountTotal = discountTypes.isDiscountPerAmount(type)
        ? discount
        : (totalWithIVA * discount) / 100
      return isGramaje
        ? formatNumberToDb((totalWithIVA - discountTotal) / (quantity / 1000))
        : formatNumberToDb((totalWithIVA - discountTotal) / quantity)
    }
  }
}

export const getTotalQuantity = ({
  quantity,
  promotionTypeId,
  promotionExtra,
}) => {
  if (promotionTypeId === promotions.PURCHASE_ITEM_FREE_UNITS) {
    return quantity + promotionExtra
  }
  return quantity
}

export const getQuantityWithoutFreeUnits = ({
  quantity,
  promotionTypeId,
  promotionExtra,
}) => {
  if (promotionTypeId === promotions.PURCHASE_ITEM_FREE_UNITS) {
    const result = quantity - promotionExtra
    if (result < 0) return result * -1
    return result
  }
  return quantity
}

export const getPromotionExtra = formPayload => {
  const { promotionTypeId, freeUnits, cost, tax } = formPayload
  switch (promotionTypeId) {
    case promotions.NONE:
      return 0
    case promotions.PURCHASE_ITEM_FREE_PRODUCT:
      return -1
    case promotions.PURCHASE_ITEM_FREE_UNITS:
      return freeUnits
    case promotions.PURCHASE_ITEM_SUBTOTAL_DISCOUNT:
      return formatNumberToDb(cost * applyTax(tax))
  }
}

export const getDiscountPercent = formPayload => {
  const { type, discount, promotionTypeId } = formPayload
  if (
    promotionTypeId === promotions.PURCHASE_ITEM_SUBTOTAL_DISCOUNT &&
    discountTypes.isDiscountPerPercent(type)
  )
    return discount
  return 0
}

export const getDiscountAmount = formPayload => {
  const { type, discount, promotionTypeId } = formPayload
  if (
    promotionTypeId === promotions.PURCHASE_ITEM_SUBTOTAL_DISCOUNT &&
    discountTypes.isDiscountPerAmount(type)
  )
    return formatNumberToDb(discount)
  return 0
}

export const getDiffDiscount = (formPayload, isGramaje) => {
  if (
    promotions.PURCHASE_ITEM_SUBTOTAL_DISCOUNT !==
      formPayload.promotionTypeId &&
    formPayload.discount > 0
  )
    return 0
  const { purchase_quantity, purchase_price, unit_cost, iva } = formPayload
  const originalTotalWithIVA =
    isGramaje === 1
      ? convertByWeightQuantity(purchase_quantity, false) *
        unit_cost *
        applyTax(iva)
      : purchase_quantity * unit_cost * applyTax(iva)
  const discountedTotalWithIVA =
    isGramaje === 1
      ? convertByWeightQuantity(purchase_quantity, false) * purchase_price
      : purchase_quantity * purchase_price
  return originalTotalWithIVA - discountedTotalWithIVA
}
