<template>
  <div class="product-extra-info__chips">
    <div
      v-if="productCanShowExtraInfo && promotionsToShow.length > 0"
      class="product-promotions"
    >
      <template v-for="(promotion, index) in promotionsToShow">
        <v-chip
          v-if="index < 1 || seeMore"
          :key="`${product.id}-promo-${index}`"
          :color="chipColor"
          label
          small
          class="px-2 product-extra-info__chip normal-cursor"
        >
          <v-icon small>mdi-sale</v-icon>
          <span class="ml-1 text-subtitle-1">{{ promotion }}</span>
        </v-chip>
      </template>
      <v-chip
        v-if="promotionsToShow.length > 1"
        color="error"
        label
        small
        class="px-2 product-extra-info__chip"
        @click.prevent.stop="seeMore = !seeMore"
      >
        <span class="text-subtitle-1">
          {{
            getTranslatedText(
              `salesView.ticket.promotions.see${seeMore ? 'Less' : 'More'}`,
              promotionsToShow.length - 1
            )
          }}
        </span>
      </v-chip>
    </div>
    <v-chip
      v-if="product.iva > 0"
      color="accent"
      label
      small
      class="product-extra-info__chip normal-cursor product-iva"
    >
      <span class="ml-1 text-subtitle-1">{{
        getTranslatedText('operationsView.detail.tax', product.iva)
      }}</span>
    </v-chip>
  </div>
</template>

<script>
import { promotions } from '@/config/promotions'

import { getTranslatedText } from '@/tools/data'
import { getAmountFromPercent, hasProductPromotion } from '@/tools/promotions'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { getTotalProductPrice } from '@/tools/ticket'
import { getQuantityWithoutFreeUnits } from '@/tools/purchases/tools'

export default {
  name: 'ProductExtraInfo',
  props: {
    product: {
      type: Object,
      required: true,
    },
    promotionTicketId: {
      type: Number,
      required: true,
    },
  },
  data() {
    return {
      seeMore: false,
    }
  },
  computed: {
    productCanShowExtraInfo() {
      return this.product.isAirtime !== 1 && this.product.isGeneric !== 1
    },
    promotionIsTicketAtCost() {
      return (
        (this.promotionTicketId === promotions.SALE_TICKET_AT_COST &&
          this.product.promotionTypeId === promotions.NONE) ||
        this.product.promotionTypeId === promotions.SALE_TICKET_AT_COST
      )
    },
    chipColor() {
      if (this.promotionIsTicketAtCost && this.product.cost <= 0) {
        return 'warning'
      }
      return 'error'
    },
    promotionsToShow() {
      if (this.product.promotions && this.product.promotions.length > 0) {
        return this.moreForLessPromotions
      }
      if (this.promotionIsTicketAtCost) return this.ticketAtCostPromotion
      if (!hasProductPromotion(this.product.promotionTypeId)) return []
      switch (this.product.promotionTypeId) {
        case promotions.PURCHASE_ITEM_FREE_PRODUCT:
        case promotions.SALE_ITEM_FREE_PRODUCT: {
          return this.freeProductPromotion
        }
        case promotions.PURCHASE_ITEM_SUBTOTAL_DISCOUNT:
          return this.discountProductPromotion
        case promotions.PURCHASE_ITEM_FREE_UNITS:
          return this.freeUnitsPromotion
      }
      return []
    },
    moreForLessPromotions() {
      return this.product.promotions.map(promo =>
        this.getTranslatedText(
          'salesView.ticket.promotions.moreForLessPromotion',
          [promo.quantity, formatNumberFromDbToCurrency(promo.total)]
        )
      )
    },
    ticketAtCostPromotion() {
      if (this.product.cost > 0) {
        return [this.getTranslatedText('salesView.ticket.promotions.atCost')]
      }
      return [
        this.getTranslatedText('salesView.ticket.promotions.atCostWithoutCost'),
      ]
    },
    freeProductPromotion() {
      return [this.getTranslatedText('operationsView.detail.freeProduct')]
    },
    freeUnitsPromotion() {
      return [
        this.getTranslatedText(
          `operationsView.detail.freeUnits${
            this.product.isGramaje === 1 ? 'ByWeight' : 'Pieces'
          }`,
          `${getQuantityWithoutFreeUnits(this.product)} + ${
            this.product.promotionExtra
          }`
        ),
      ]
    },
    discountProductPromotion() {
      const costWithoutPromotion = getTotalProductPrice(
        this.product,
        'costWithoutPromotion'
      )
      let discount = formatNumberFromDbToCurrency(
        costWithoutPromotion - getTotalProductPrice(this.product)
      )
      if (this.product.discount > 0) {
        const amountDiscounted = formatNumberFromDbToCurrency(
          getAmountFromPercent(this.product.discount, costWithoutPromotion)
        )
        discount = `${this.product.discount}% (${amountDiscounted})`
      }
      return [
        this.getTranslatedText(
          'operationsView.detail.amountDiscount',
          discount
        ),
      ]
    },
  },
  methods: {
    getTranslatedText,
  },
  mounted() {
    this.$watch(
      () => this.promotionsToShow.length,
      newValue => {
        this.seeMore = this.seeMore && newValue > 1
      }
    )
  },
}
</script>

<style scoped lang="scss">
.product-extra-info {
  &__chips {
    display: flex;
    gap: 4px;
    flex-wrap: wrap;
    .product-promotions {
      display: flex;
      gap: 4px;
      flex-wrap: wrap;
    }
  }
  &__chip {
    flex-shrink: 0;
    &.normal-cursor:hover {
      cursor: default;
    }
  }
}
</style>
