<template>
  <div>
    <ItemsListHeaders
      :is-sale-ticket="isSaleTicket"
      :is-purchase-ticket="isPurchaseTicket"
      :operation-type="operationType"
    />
    <p class="small-font">
      ----------------------------------------------------------
    </p>
    <ProductsListTicket
      :products="products"
      :operation-type="operationType"
      :is-purchase-ticket="isPurchaseTicket"
    />
    <ReturnProductsListTicket
      v-if="!!returnProducts.length"
      :return-products="returnProducts"
    />
    <CombosListTicket v-if="!!combos.length" :combos="combos" />
  </div>
</template>

<script>
import { idOperations } from '@/config/cashOperationsVariables'

import ItemsListHeaders from '@/components/TicketToPrint/ItemsListTicket/ItemsListHeaders'
import ProductsListTicket from '@/components/TicketToPrint/ItemsListTicket/ProductsListTicket'
import ReturnProductsListTicket from '@/components/TicketToPrint/ItemsListTicket/ReturnProductsListTicket'
import CombosListTicket from '@/components/TicketToPrint/ItemsListTicket/CombosListTicket'

export default {
  name: 'ItemsListTicket',
  components: {
    CombosListTicket,
    ReturnProductsListTicket,
    ProductsListTicket,
    ItemsListHeaders,
  },
  props: {
    products: {
      type: Array,
      required: true,
    },
    returnProducts: {
      type: Array,
      default: () => [],
    },
    operationType: {
      type: Number,
      default: idOperations.ID_OPERATION_CREDIT_SALE,
    },
    isSaleTicket: {
      type: Boolean,
      default: false,
    },
    isPurchaseTicket: {
      type: Boolean,
      default: false,
    },
    isCopy: {
      type: Boolean,
      default: false,
    },
    combos: {
      type: Array,
      default: () => [],
    },
  },
}
</script>
