<template>
  <div>
    <div
      v-for="product in products"
      :key="product.id"
      class="product-container"
    >
      <span>{{ product.name }} {{ product.description }}</span>
      <div class="product-detail" :class="`cols-${isPurchaseTicket ? 4 : 3}`">
        <span>
          {{ product.quantity }}
        </span>
        <span :class="{ centered: !isPurchaseTicket }">{{
          formatNumberFromDbToCurrency(getUnitPrice(product))
        }}</span>
        <span v-if="isPurchaseTicket" class="centered">{{ product.iva }}%</span>
        <span class="text-right">
          {{ formatNumberFromDbToCurrency(getTotalPrice(product)) }}
        </span>
      </div>
      <div v-if="hasCustomPromotion(product)">
        <div
          v-for="(promotion, index) in product.promotions"
          :key="`${promotion.id}-${index}`"
          class="product-detail product-promotion"
        >
          <span>
            >
            {{
              getTranslatedText(
                'ticketToPrint.productsList.promotion.moreForLess',
                [
                  promotion.quantity,
                  formatNumberFromDbToCurrency(promotion.total),
                ]
              )
            }}
          </span>
        </div>
      </div>
      <div
        v-else-if="
          hasProductPromotion(product.promotionTypeId) &&
            !isTicketAtCostInProductGeneric(product)
        "
        class="product-detail product-promotion"
      >
        <span> > {{ getPromotionText(product) }} </span>
      </div>
    </div>
  </div>
</template>

<script>
import { idOperations } from '@/config/cashOperationsVariables'

import { promotions } from '@/config/promotions'

import itemAddedFrom from '@/config/itemAddedFrom'

import salesTools from '@/tools/sales'
import {
  convertByWeightQuantity,
  formatNumberFromDbToCurrency,
} from '@/tools/numbersFormat'
import {
  getTotalProductPriceOwnerSale,
  getTotalProductPriceWithPromotion,
} from '@/tools/ticket'
import { applyTax, getQuantityWithoutFreeUnits } from '@/tools/purchases/tools'
import { getTranslatedText } from '@/tools/data'
import { hasProductPromotion } from '@/tools/promotions'

export default {
  name: 'ProductsListTicket',
  props: {
    products: {
      type: Array,
      required: true,
    },
    operationType: {
      type: Number,
      default: idOperations.ID_OPERATION_CREDIT_SALE,
    },
    isPurchaseTicket: {
      type: Boolean,
      default: false,
    },
  },
  methods: {
    getTranslatedText,
    formatNumberFromDbToCurrency,
    hasProductPromotion,
    getUnitPrice(product) {
      if (salesTools.isOwnerSale(this.operationType)) {
        return salesTools.getProductCost(product)
      }
      return product.price
    },
    getTotalPrice(product) {
      if (salesTools.isOwnerSale(this.operationType)) {
        return getTotalProductPriceOwnerSale(product)
      }
      return getTotalProductPriceWithPromotion({
        ...product,
        promotions: [],
        discountPercent: product.discount,
        discountAmount: this.getDiscountAmount(product),
        costWithoutPromotion:
          product.costWithoutTaxAndPromotion * applyTax(product.iva),
      })
    },
    getDiscountAmount(product) {
      const {
        isGramaje,
        quantity,
        costWithoutTaxAndPromotion,
        iva,
        price,
      } = product
      const originalTotalWithIVA =
        isGramaje === 1
          ? convertByWeightQuantity(quantity, false) *
            costWithoutTaxAndPromotion *
            applyTax(iva)
          : quantity * costWithoutTaxAndPromotion * applyTax(iva)
      const discountedTotalWithIVA =
        isGramaje === 1
          ? convertByWeightQuantity(quantity, false) * price
          : quantity * price
      return originalTotalWithIVA - discountedTotalWithIVA
    },
    hasCustomPromotion(product) {
      return product.promotions && product.promotions.length > 0
    },
    isTicketAtCostInProductGeneric(product) {
      return (
        product.promotionTypeId === promotions.SALE_TICKET_AT_COST &&
        product.priceFrom === itemAddedFrom.FROM_PRICE
      )
    },
    getPromotionText(product) {
      switch (product.promotionTypeId) {
        case promotions.PURCHASE_ITEM_FREE_PRODUCT:
        case promotions.SALE_ITEM_FREE_PRODUCT:
          return this.getTranslatedText(
            'ticketToPrint.productsList.promotion.freeProduct'
          )
        case promotions.PURCHASE_ITEM_FREE_UNITS:
          return this.getTranslatedText(
            `ticketToPrint.productsList.promotion.freeUnits${
              product.isGramaje === 1 ? 'ByWeight' : 'Pieces'
            }`,
            `${getQuantityWithoutFreeUnits({
              ...product,
              promotionType: product.promotionTypeId,
            })} + ${product.promotionExtra}`
          )
        case promotions.SALE_TICKET_AT_COST:
          return this.getTranslatedText(
            `ticketToPrint.productsList.promotion.product${
              product.cost > 0 ? 'AtCost' : 'WithoutCost'
            }`
          )
        default: {
          let amountDiscounted =
            (product.promotionExtra - product.price) * product.quantity
          if (product.isGramaje === 1) {
            amountDiscounted = Number((amountDiscounted / 1000).toFixed(0))
          }
          const discount =
            product.discount > 0
              ? `${product.discount}% (${formatNumberFromDbToCurrency(
                  amountDiscounted
                )})`
              : formatNumberFromDbToCurrency(amountDiscounted)
          return `${this.getTranslatedText(
            'ticketToPrint.productsList.promotion.discount'
          )}: ${discount}`
        }
      }
    },
  },
}
</script>
