<template>
  <div>
    <div
      v-for="product in returnProducts"
      :key="`${product.id}-RP`"
      class="product-container"
    >
      <div v-if="!isReturnTypeDiscount(product.returnType)">
        <span>{{ product.nameChange }}</span>
        <div class="product-detail cols-4">
          <span>
            {{ product.quantityChange }}
          </span>
          <span>
            {{ formatNumberFromDbToCurrency(product.priceChange) }}
          </span>
          <span class="centered"> - </span>
          <span class="text-right">
            {{ formatNumberFromDbToCurrency(0) }}
          </span>
        </div>
        <div class="product-detail product-promotion">
          <span>
            >
            {{
              getTranslatedText(
                'ticketToPrint.productsList.returnProducts.productToChange'
              )
            }}
          </span>
        </div>
      </div>
      <div>
        <span>{{ product.name }}</span>
        <div class="product-detail cols-4">
          <span> {{ product.quantity }} </span>
          <span>
            {{ formatNumberFromDbToCurrency(product.price) }}
          </span>
          <span class="centered"> - </span>
          <span
            class="text-right"
            v-if="isReturnTypeDiscount(product.returnType)"
          >
            -{{ formatNumberFromDbToCurrency(product.amountToDiscount) }}
          </span>
          <span v-else class="text-right">
            {{ formatNumberFromDbToCurrency(0) }}
          </span>
        </div>
        <div class="product-detail product-promotion">
          <span>
            >
            {{
              getTranslatedText(
                'ticketToPrint.productsList.returnProducts.returnProduct'
              )
            }}
          </span>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { returnTypes } from '@/config/returnProductTypes'

import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { getTranslatedText } from '@/tools/data'

export default {
  name: 'ReturnProductsListTicket',
  props: {
    returnProducts: {
      type: Array,
      default: () => [],
    },
  },
  methods: {
    getTranslatedText,
    formatNumberFromDbToCurrency,
    isReturnTypeDiscount(returnType) {
      return returnType === returnTypes.DISCOUNT
    },
  },
}
</script>
