<template>
  <v-hover v-model="isHover">
    <div
      class="product-ticket"
      :class="{ 'pl-6 pr-2 pt-3': !isOperationSection }"
    >
      <ActionsButtons
        v-if="Object.keys(actions).length > 0"
        :is-hover="isHover"
        :actions="actions"
      />
      <v-card
        flat
        :color="cardColor"
        class="py-2 px-4 product-ticket__card"
        v-on="clickCard"
      >
        <div class="product-ticket__quantity">
          <ProductQuantity :product="product" />
        </div>
        <div class="product-ticket__info pl-1">
          <ProductInfo
            :product="product"
            :pay-option="payOption"
            :promotion-ticket-id="promotionTicketId"
            :price-key="priceKey"
            :price-without-promotion-key="priceWithoutPromotionKey"
          />
          <ProductExtraInfo
            :product="product"
            :promotion-ticket-id="promotionTicketId"
            class="mt-1"
          />
        </div>
        <div class="product-ticket__total">
          <ProductTotal
            :product="product"
            :pay-option="payOption"
            :promotion-ticket-id="promotionTicketId"
            :price-key="priceKey"
          />
        </div>
      </v-card>
    </div>
  </v-hover>
</template>

<script>
import ActionsButtons from '@/components/shared/Ticket/Product/ActionsButtons'
import ProductQuantity from '@/components/shared/Ticket/Product/ProductQuantity'
import ProductInfo from '@/components/shared/Ticket/Product/ProductInfo'
import ProductExtraInfo from '@/components/shared/Ticket/Product/ProductExtraInfo'
import ProductTotal from '@/components/shared/Ticket/Product/ProductTotal'

export default {
  name: 'Product',
  components: {
    ActionsButtons,
    ProductQuantity,
    ProductInfo,
    ProductExtraInfo,
    ProductTotal,
  },
  props: {
    product: {
      type: Object,
      required: true,
    },
    actions: {
      type: Object,
      default: () => ({}),
    },
    payOption: {
      type: [String, Number],
      default: 'cash',
    },
    promotionTicketId: {
      type: Number,
      default: 0,
    },
    priceKey: {
      type: String,
      required: true,
    },
    priceWithoutPromotionKey: {
      type: String,
      required: true,
    },
  },
  data() {
    return {
      isHover: false,
    }
  },
  computed: {
    clickCard() {
      if (this.isOperationSection) return {}
      return {
        click: () => this.$emit('productCardWasClicked'),
      }
    },
    isOperationSection() {
      return (
        this.$route.name === 'Operations' || this.$route.name === 'Customers'
      )
    },
    cardColor() {
      return this.isOperationSection
        ? 'cardBackgroundSecondary'
        : 'cardBackgroundPrimary'
    },
  },
}
</script>

<style scoped lang="scss">
.product-ticket {
  position: relative;
  &__card {
    display: flex;
    gap: 12px;
    border-radius: 10px;
    &:focus:before {
      opacity: 0;
    }
  }
  &__quantity {
    width: 60px;
  }
  &__info {
    flex: 1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  &__total {
    white-space: nowrap;
    text-align: end;
  }
}
</style>
