<template>
  <div class="product-container">
    <span>
      {{ getTranslatedText('ticketToPrint.productsList.headers.product') }}
    </span>
    <div class="product-detail" :class="`cols-${isPurchaseTicket ? 4 : 3}`">
      <span>
        {{ getTranslatedText('ticketToPrint.productsList.headers.quantity') }}
      </span>
      <span v-if="isSaleTicket" class="centered">
        {{ getTranslatedText('ticketToPrint.productsList.headers.price') }}
      </span>
      <span v-else :class="{ centered: isOwnerSale(operationType) }">
        {{ getTranslatedText('ticketToPrint.productsList.headers.cost') }}
      </span>
      <span v-if="isPurchaseTicket" class="centered">
        {{ getTranslatedText('ticketToPrint.productsList.headers.iva') }}
      </span>
      <span class="text-right">
        {{ getTranslatedText('ticketToPrint.productsList.headers.total') }}
      </span>
    </div>
  </div>
</template>

<script>
import { idOperations } from '@/config/cashOperationsVariables'

import { getTranslatedText } from '@/tools/data'
import salesTools from '@/tools/sales'

export default {
  name: 'ItemsListHeaders',
  props: {
    isPurchaseTicket: {
      type: Boolean,
      default: false,
    },
    isSaleTicket: {
      type: Boolean,
      default: false,
    },
    operationType: {
      type: Number,
      default: idOperations.ID_OPERATION_CREDIT_SALE,
    },
  },
  methods: { getTranslatedText, isOwnerSale: salesTools.isOwnerSale },
}
</script>
